def count_segment_length(grid, start_row, start_col, direction):
    """Count total cells from start going in a direction"""
    dr, dc = direction
    r, c = start_row, start_col
    total_len = 0
    while True:
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            if grid[r][c] == grid[start_row][start_col]:
                total_len += 1
                r, c = r + dr, c + dc
            else:
                break
        else:
            break
    return total_len

def identify_foreground_and_background(grid):
    """Identify background (most common) and foreground (less common) values"""
    val_counts = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            val_counts[val] = val_counts.get(val, 0) + 1

    # Most common = background, least common among patterns = foreground
    sorted_vals = sorted(val_counts.items(), key=lambda x: x[1])
    print(f"Value counts: {val_counts}")

    # Background is the one with highest count
    bg_val = max(val_counts, key=val_counts.get)
    fg_candidates = [(v, cnt) for v, cnt in sorted_vals[:-1]]  # exclude background

    if fg_candidates:
        # If there are multiple candidate foregrounds, the one with fewest cells 
        # that forms connected patterns might be the intended foreground
        # For demo: 6 cells form the pattern we care about
        fg_val = fg_candidates[-1][0]  # pick second-most-common or analyze further
    else:
        fg_val = None

    print(f"Background: {bg_val}, Foreground candidate: {fg_val}")
    return bg_val, fg_val

def solve_arc_transform(grid):
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    bg_val, fg_val = identify_foreground_and_background(grid)

    if fg_val is None:
        print("No foreground identified - returning copy")
        return result

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]

            # Only transform foreground value
            if val != fg_val:
                continue

            # Count orthogonal neighbors with same value
            ortho_neighbors = get_orthogonal_neighbors(grid, r, c)
            same_val_neighbors = [(nr, nc) for nr, nc in ortho_neighbors 
                                  if grid[nr][nc] == val]
            adj_count = len(same_val_neighbors)

            if adj_count >= 2:
                # Junction or corner - always changes to 2
                result[r][c] = 2
            elif adj_count == 1:
                # Endpoint - check segment length
                direction = None
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val:
                        direction = (dr, dc)
                        break

                if direction:
                    seg_len = count_segment_length(grid, r, c, direction)
                    # SHORT endpoint (seg_len <= 3) STAYS unchanged
                    # LONG endpoint (seg_len > 3) CHANGES to 2
                    if seg_len > 3:
                        result[r][c] = 2
                    # else: short endpoint stays as fg_val
            # adj_count == 0: isolated cells stay unchanged

    return result

